cat > /home/user/dialog_branching_system/scripts/DialogPlayer.gd <<EOF
extends Node
class_name DialogPlayer

signal line_shown(speaker: String, text: String, choices_labels: Array)
signal dialog_finished

@export var tree: DialogTree

var current_node: DialogNode = null
var flags: Dictionary = {}

func start() -> void:
	if not tree:
		return
	current_node = tree.get_node(tree.start_id)
	_emit_line()

func advance(choice_index: int = -1) -> void:
	if current_node == null:
		return
	if not current_node.choices.is_empty():
		if choice_index >= 0 and choice_index < current_node.choices.size():
			var choice = current_node.choices[choice_index]
			if choice.condition_flag.is_empty() or flags.get(choice.condition_flag, false):
				current_node = tree.get_node(choice.next_id)
			else:
				return
		else:
			return
	elif not current_node.next_id.is_empty():
		current_node = tree.get_node(current_node.next_id)
	else:
		dialog_finished.emit()
		current_node = null
		return
	if current_node:
		_emit_line()
	else:
		dialog_finished.emit()

func set_flag(name: StringName) -> void:
	flags[name] = true

func has_flag(name: StringName) -> bool:
	return flags.get(name, false)

func _emit_line() -> void:
	var labels: Array = []
	for choice in current_node.choices:
		if choice.condition_flag.is_empty() or flags.get(choice.condition_flag, false):
			labels.append(choice.label)
	line_shown.emit(current_node.speaker, current_node.text, labels)
EOF

