extends Control

@export var player: DialogPlayer

@onready var speaker_label = $SpeakerLabel
@onready var text_label = $TextLabel
@onready var choices_container = $ChoicesContainer

func _ready() -> void:
	if player:
		player.line_shown.connect(_on_line_shown)

func _on_line_shown(speaker: String, text: String, labels: Array) -> void:
	speaker_label.text = speaker
	text_label.text = text
	for child in choices_container.get_children():
		child.queue_free()
	for i in range(labels.size()):
		var btn = Button.new()
		btn.text = labels[i]
		btn.pressed.connect(func(): player.advance(i))
		choices_container.add_child(btn)
EOF
